import{_ as d,C as e,o as l,c as p,j as a,a as o,E as n,a3 as g}from"./chunks/framework.D4-ViStF.js";const k=JSON.parse('{"title":"坐忘论·序说","description":"坐忘论开篇总论精读：人贵其生、生贵其道；五组倒置；由反省而立七条修道阶次。","frontmatter":{"title":"坐忘论·序说","description":"坐忘论开篇总论精读：人贵其生、生贵其道；五组倒置；由反省而立七条修道阶次。","category":"guide","aliases":["坐忘论序说","坐忘论总论","坐忘论精读之一"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/preface.md","filePath":"daoism/daoist-classics/zuowang-lun/preface.md","lastUpdated":1789714390000}'),h={name:"daoism/daoist-classics/zuowang-lun/preface.md"};function c(u,t,m,b,x,f){const r=e("DaoReadingPrelude"),s=e("DaoTextReading"),i=e("DaoKeywordCards");return l(),p("div",null,[t[0]||(t[0]=a("h1",{id:"坐忘论·序说",tabindex:"-1"},[o("坐忘论·序说 "),a("a",{class:"header-anchor",href:"#坐忘论·序说","aria-label":'Permalink to "坐忘论·序说"'},"​")],-1)),n(r,{title:"人贵其生，生贵其道",summary:"开篇总论不下断语，先摆出一幅「倒置」的图景：世人怕生死之苦，却又贪爱造成生死的业；重道德之名，却轻道德之行。它并不先讲如何打坐，而是先追问：我们口头上珍惜生命，实际生活却是否一直在耗损生命？",points:[{label:"先说正",text:"人最可贵的是生，生最可贵的是道——鱼之于水，不可须臾离。"},{label:"再说倒",text:"厌果而爱因、重名而轻行、以贪求逐无为，愈勤苦愈乖背。"},{label:"后立次",text:"审惟倒置，穷而思通，迷而思复，于是略成七条修道阶次。"}],hint:"读此篇可留意两组比喻：「若鱼之有水」说道是本分之事，「积雪为粮，磨砖作镜」说方向错了便是徒劳。"}),t[1]||(t[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[o("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),t[2]||(t[2]=a("p",null,[a("strong",null,"一、生命与道")],-1)),n(s,{paragraphs:["夫人之所贵者生，生之所贵者道。人之有道，若鱼之有水。涸辙之鱼，犹希斗水；弱丧之俗，无情造道。"]}),t[3]||(t[3]=a("p",null,[a("strong",null,"二、世俗生活的根本倒置")],-1)),n(s,{paragraphs:["恶生死之苦，爱生死之业；重道德之名，轻道德之行。喜色味为得志，鄙恬素为穷辱。竭难得之货，市来生之福；纵易染之情，丧今身之道。自云智巧，如梦如迷。","将生灭质，求无为道，亦犹积雪为粮，磨砖作镜，愈见勤苦，弥益乖背。"]}),t[4]||(t[4]=a("p",null,[a("strong",null,"三、由反省而建立七阶")],-1)),n(s,{paragraphs:["审惟倒置，何甚如之！穷而思通，迷而思复，寸阴如璧，愧叹交深。","是以恭寻经旨，而与心法相应者，略成七条，以为修道阶次，枢翼附焉。"]}),t[5]||(t[5]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),n(i,{items:[{term:"涸辙之鱼",pinyin:["hé","zhé","zhī","yú"],meaning:"典出《庄子·外物》涸辙之鲋：车辙水洼里的鱼，急求斗升之水以活命。此处谓求生之切，反衬人失道而不自知。"},{term:"弱丧",pinyin:["ruò","sàng"],meaning:"语本《庄子·齐物论》「弱丧而不知归者」：幼遭丧乱离乡而忘归路。喻世人远离本根却把漂泊当常态。"},{term:"无情造道",pinyin:["wú","qíng","zào","dào"],meaning:"情，真切意向。谓世俗之人对趋向大道竟无真切愿望：对名利有情有行，对返本修道则无心实行。"},{term:"业",pinyin:["yè"],meaning:"身口意所造作并产生后果的行为。此处带明显佛教色彩：爱其业，即贪爱造苦之因。"},{term:"恬素",pinyin:["tián","sù"],meaning:"恬淡朴素。与「色味」「得志」相对。"},{term:"市",pinyin:["shì"],meaning:"买取、交易。「市来生之福」，谓以财货交换未来福报——批评把修道当成交易。"},{term:"积雪为粮，磨砖作镜",pinyin:["jī","xuě","wéi","liáng","mó","zhuān","zuò","jìng"],meaning:"两个比喻：以雪作粮、磨砖成镜，皆材质与方向不对而徒劳。谓以贪求修无为，愈用力愈相违。"},{term:"乖背",pinyin:["guāi","bèi"],meaning:"违背、相背。弥益乖背，谓越发背离所求之道。"},{term:"寸阴如璧",pinyin:["cùn","yīn","rú","bì"],meaning:"一寸光阴贵重如玉璧。语近《淮南子》「圣人不贵尺之璧而重寸之阴」。"},{term:"枢翼",pinyin:["shū","yì"],meaning:"枢为门户转动之要，翼为辅助。此处指后附的《坐忘枢翼》一篇。"}]}),t[6]||(t[6]=g(`<h2 id="【解读层】精读" tabindex="-1">【解读层】精读 <a class="header-anchor" href="#【解读层】精读" aria-label="Permalink to &quot;【解读层】精读&quot;">​</a></h2><h3 id="一、生命与道" tabindex="-1">一、生命与道 <a class="header-anchor" href="#一、生命与道" aria-label="Permalink to &quot;一、生命与道&quot;">​</a></h3><p>「人之所贵者生，生之所贵者道」确立两层价值：人所贵者是<strong>生</strong>，而生所贵者是<strong>道</strong>。生很宝贵，却不是最孤立的目标——若为延寿而终日焦虑贪求、耗损形神，反而违背了生命之道。故「生之所贵者道」至少有两层：道是生命的根本（顺道则身心自和），生命的价值在于成道（生命是返本复性的条件）。</p><blockquote><p>贵生，不是执生；养生，最终是为了成道。</p></blockquote><p>「人之有道，若鱼之有水」——道不是额外的装饰，而是生命赖以成立的环境。鱼在水中不觉水之重要，离水方知不可活；人对道亦然：清静、自然、节制本是生命所需，人在日用中习以为常，反倒不断向外追逐。「有道」也不只是知道「道」这个概念，而是身能顺其自然、心不被外物长期役使、行为与所知相应。</p><p>「涸辙之鱼，犹希斗水」化用《庄子·外物》涸辙之鲋的故事。困鱼尚且求水，而身心离道的人却未必知道求道——这里的对比很鲜明：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>涸辙之鱼：知道生命缺水 → 急切求水</span></span>
<span class="line"><span>迷失之人：不知心神离道 → 继续追逐耗损之物</span></span></code></pre></div><p>人的危险不只是「失道」，更在于<strong>失道而不自知</strong>。</p><p>「弱丧之俗，无情造道」：世人如同幼年离乡、久而忘归的人，远离生命本根，却已把漂泊当成正常状态；对名利声色有情、有求、有行动，对返本修道却无情、无心、无实行。这不是不知道「道」这个名词，而是没有把道当作真正要走的路。</p><h3 id="二、世俗生活的根本倒置" tabindex="-1">二、世俗生活的根本倒置 <a class="header-anchor" href="#二、世俗生活的根本倒置" aria-label="Permalink to &quot;二、世俗生活的根本倒置&quot;">​</a></h3><p><strong>「恶生死之苦，爱生死之业」</strong>——人厌恶生死轮转之苦，却又喜爱那些不断造成此苦的行为。因果的循环是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>欲望与执著 → 推动选择与行为 → 行为形成习惯与后果</span></span>
<span class="line"><span>        → 习惯又加强欲望与执著 → 烦恼、生死不断延续</span></span></code></pre></div><p>这只是第一重倒置：<strong>厌果而爱因</strong>。人往往如此——厌恶焦虑，却不肯减少攀比；企求清静，却持续经营使心不静的关系。</p><p><strong>「重道德之名，轻道德之行」</strong>——第二重倒置：<strong>重名而轻实</strong>。喜欢谈论清静却不肯减少事务，尊重坐忘之名却不愿真正收心。这也预告了《收心》的批评：「法之妙用，在于能行，不在于能言。」司马承祯自己正是「恭寻经旨」，他反对的不是学经，而是把<strong>知道、谈论、实行</strong>混为一谈。</p><p><strong>「喜色味为得志，鄙恬素为穷辱」</strong>——第三重倒置：<strong>以欲望满足为成功，以不受欲望支配为失败</strong>。世俗的尺度是向外增加（拥有越多越成功、事务越忙越有能力）；修道的方向恰好相反（外缘渐少、欲望渐薄、事务渐简而不以名位动心）。这不是说匮乏就是道，也不是把受苦理想化；真正的问题是：我们是否把不断消费与感官刺激误认成生命的完成。恬素不是不得志之后的被迫退缩，而是<strong>主动选择的生命尺度</strong>。</p><p><strong>「竭难得之货，市来生之福」</strong>——耗尽今生财货，试图买取来生福报。批评的是一种功利化的宗教心理：把修道理解成交易（我付出财货，便应换得福寿功德）。问题不在正常布施，而在以<strong>求报之心</strong>行善——内里仍是计算得失，并未放下贪求。</p><p><strong>「纵易染之情，丧今身之道」</strong>——与上句构成尖锐对照：为遥远的来生百般经营，对今身之道却任其丧失。这不是否定来生观念，而是指出：若当下一念都不能返照，所谓来生福报也可能只是欲望向未来的延长。</p><p><strong>「自云智巧，如梦如迷」</strong>——智巧只负责寻找更有效的手段，却不追问目标是否正确。「如何获得更多」可以计算得很精密，而「这些追求是否真正有益于生命」从未被审察。故智巧不等于智慧：</p><table tabindex="0"><thead><tr><th>智巧</th><th>智慧</th></tr></thead><tbody><tr><td>善于计算手段</td><td>能审察根本方向</td></tr><tr><td>追求更多占有</td><td>知道何者应取、何者应舍</td></tr><tr><td>向外经营</td><td>能够返观自身</td></tr><tr><td>使事情更复杂</td><td>使生命返于简要</td></tr></tbody></table><p><strong>「将生灭质，求无为道，亦犹积雪为粮，磨砖作镜」</strong>——一面依生灭世界的占有与交易逻辑生活，一面又想借此得到无为之道，方法上自相矛盾。积雪不能养命，磨砖不能成镜：<strong>勤奋本身不能纠正方向上的错误</strong>。</p><p>（「磨砖作镜」最著名的语境是禅宗南岳怀让点化马祖道一。此处不必断定《坐忘论》直接取自该故事；更稳妥的理解是，它属于唐代道佛修行语境中十分有力的共同譬喻。）</p><p><strong>「愈见勤苦，弥益乖背」</strong>——这不是否定勤行（《敬信》马上就说「加之勤行，得道必矣」），而是否定<strong>方向错误的努力</strong>。修道首先不是问「我付出了多少」，而是问：</p><blockquote><p>我的用力，是在减少执著，还是在借修道建立更大的执著？</p></blockquote><h3 id="三、看见倒置-才可能开始返归" tabindex="-1">三、看见倒置，才可能开始返归 <a class="header-anchor" href="#三、看见倒置-才可能开始返归" aria-label="Permalink to &quot;三、看见倒置，才可能开始返归&quot;">​</a></h3><p><strong>「审惟倒置，何甚如之」</strong>——前文的倒置可以整理为五组：</p><table tabindex="0"><thead><tr><th>本来应该</th><th>实际却是</th></tr></thead><tbody><tr><td>贵生而修道</td><td>贵生却不断耗生</td></tr><tr><td>厌苦而断苦因</td><td>厌恶苦果却贪爱苦因</td></tr><tr><td>重实际修行</td><td>只重道德之名</td></tr><tr><td>珍惜当下之道</td><td>经营遥远的来生福报</td></tr><tr><td>以无欲契无为、以智慧返本</td><td>以贪求逐无为、以智巧强化外逐</td></tr></tbody></table><p>坐忘的开始，不是马上停止全部念头，而是<strong>先看见这种倒置</strong>。否则后面的断缘、收心很容易被误解成损失；只有发现原来的生活方向正在损害自己，才可能真正愿意返转。</p><p><strong>「穷而思通，迷而思复」</strong>——「穷」与「通」有《易》学意味（穷则变，变则通，通则久）；「迷」与「复」则是全书的修行结构：迷是心神外驰、以苦为乐；复是收心返照、归根复命。「复」不是增加新东西，而是回到原本具有、后来受遮蔽的根性——与《天隐子》「修我灵气」「遂我自然」完全一致。</p><p><strong>「寸阴如璧，愧叹交深」</strong>——「愧」不是要人陷入自责，而是清醒地意识到：过去长期随境外驰、把精力耗费在非必要之事上、知而未行。但这份紧迫感也不能变成焦躁——《收心》与《枢翼》都会提醒：束心过急，反而可能成病。</p><p><strong>「恭寻经旨，而与心法相应者，略成七条，以为修道阶次」</strong>——写作方式有两个来源：<strong>经旨</strong>（广泛引《老子》《庄子》《西升经》《生神经》等）与<strong>与心法相应</strong>（只取能落到实处者）。故本书不是经文汇编，而是「经典依据 + 修心经验 + 次第组织」。</p><p>七篇的「阶次」由浅入深：敬信建立方向 → 断缘减少牵引 → 收心治理散乱 → 简事重整生活 → 真观解除执著 → 泰定定慧成熟 → 得道形神合道。但这<strong>不是僵硬的线性关系</strong>：没有敬信则断缘难持，外缘不断则收心难安，不简事务则收心易反复，没有真观则压住的欲望仍会再起——七篇在实际修习中彼此循环、互相巩固。</p><p>「枢翼附焉」：《坐忘枢翼》总括七篇要点、补充具体收心方法、说明用力过紧与过松的偏差、讨论定慧关系，并列出心之五时与身之七候。</p><h3 id="引经据典" tabindex="-1">引经据典 <a class="header-anchor" href="#引经据典" aria-label="Permalink to &quot;引经据典&quot;">​</a></h3><table tabindex="0"><thead><tr><th>引文</th><th>出处</th><th>转化</th></tr></thead><tbody><tr><td>涸辙之鱼</td><td>《庄子·外物》</td><td>人离道如鱼离水；修道是当前生命的根本需要，不能无限推迟</td></tr><tr><td>弱丧</td><td>《庄子·齐物论》</td><td>本来依道而生，却因长期逐物而忘记生命归宿</td></tr><tr><td>难得之货</td><td>《道德经》第三章</td><td>批评为财货耗尽精神，甚至把修行纳入交易</td></tr><tr><td>无为道</td><td>《道德经》核心观念</td><td>手段若不断强化欲望，便与目标相反</td></tr><tr><td>穷而思通</td><td>《易传》穷变通久</td><td>生命入困局 → 审察方向 → 转变习惯 → 恢复通达</td></tr><tr><td>磨砖作镜</td><td>唐代道佛语境</td><td>材料与方向不对，单纯增加努力不能达成目标</td></tr></tbody></table><p>逐条的原典语境与考订见<a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">《引经据典》</a>。</p><h3 id="论证结构" tabindex="-1">论证结构 <a class="header-anchor" href="#论证结构" aria-label="Permalink to &quot;论证结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一、确立价值    人贵生，生贵道；人离道，如鱼离水</span></span>
<span class="line"><span>二、指出现实矛盾  厌苦果而爱苦因；重名而轻行；以声色财货为成功</span></span>
<span class="line"><span>三、指出方法错误  以交易心求福、以染著心求道、以有为贪求追逐无为</span></span>
<span class="line"><span>四、开始反省      知其倒置，穷而思通，迷而思复，珍惜光阴</span></span>
<span class="line"><span>五、建立道路      恭寻经旨、与心法相应，略成七条阶次，附以枢翼</span></span></code></pre></div><h3 id="容易误解的地方" tabindex="-1">容易误解的地方 <a class="header-anchor" href="#容易误解的地方" aria-label="Permalink to &quot;容易误解的地方&quot;">​</a></h3><ol><li><strong>「贵生」不等于贪生怕死</strong>——前者引向节制与安定，后者反而制造恐惧与焦虑。</li><li><strong>「恬素」不等于贫穷才有道</strong>——批评的是把奢靡当唯一成功标准；真正的尺度是：外物足以养生，而不反过来役使心神。</li><li><strong>「来生之福」不等于否定一切布施</strong>——问题在「市」：以交易求报之心购买福报，未必能解除我执。</li><li><strong>「磨砖作镜」不等于打坐无用</strong>——它批评的是只守外在姿势、不处理欲望执著、把坐得久当得道。本书后面明确要求「安坐」，否定的是错误用心，而非坐修。</li><li><strong>「愧叹交深」不等于沉溺自责</strong>——惭愧若能转为改变，就是返归的起点；若只变成自我否定，又会形成新的心病。</li></ol><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h3><p>总论最核心的一句话可以归结为：</p><blockquote><p><strong>真正的修道，不是给原来的欲望生活再加上一个「道」的名称，而是辨认并扭转那些一面求生、一面伤生，一面求道、一面背道的生活方向。</strong></p></blockquote><p>它不从盘坐姿势开始，而从一场价值反省开始：起点是「贵生」，转折是「见倒」，方向是「思复」，方法则是「七阶」。</p><p>下一篇<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-01">《敬信》</a>将从七阶第一步开始回答：既然大道无形无象，人为什么能够相信它？这种「信」又怎样避免沦为盲从，而成为实际修行的根与蒂？</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》总览</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">全书引读</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">引经据典</a></li><li>下一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-01">敬信一</a></li><li>《天隐子》对应：<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-1">神仙一</a>（人本有灵气，修养而复归）、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-2">易简二</a>（反对言行相违）</li><li>跨篇的对应与差异，见<a href="/Dao/daoism/daoist-classics/zuowang-lun/guide#八与天隐子的对应与差异">《全书引读》· 与《天隐子》的对应与差异</a></li></ul>`,46))])}const q=d(h,[["render",c]]);export{k as __pageData,q as default};
